   379  static void ProcessParamStack(char *outbuf, int *outix, int n_param_stack, PARAM_STACK *param_stack, int *speech_parameters)
   380  {
   381          // Set the speech parameters from the parameter stack
   382          int param;
   383          int ix;
   384          int value;
   385          char buf[20];
   386          int new_parameters[N_SPEECH_PARAM];
   387          static char cmd_letter[N_SPEECH_PARAM] = { 0, 'S', 'A', 'P', 'R', 0, 'C', 0, 0, 0, 0, 0, 'F' }; // embedded command letters
   388
   389          for (param = 0; param < N_SPEECH_PARAM; param++)
   390                  new_parameters[param] = -1;
   880                  if (terminator) {
   881                          if (value > 0xfff) {
   882                                  // scale down the value and set a scaling indicator bit
   883                                  value = value / 32;
   884                                  if (value > 0xfff)
   885                                          value = 0xfff;
   886                                  terminator |= CLAUSE_PAUSE_LONG;
   887                          }
   888                          return terminator + value;
   889                  }
   890                  break;
   891          case SSML_SPEAK:
   892                  if ((attr1 = GetSsmlAttribute(px, "xml:base")) != NULL) {
   893                          attrcopy_utf8(buf, attr1, sizeof(buf));
   894                          if ((index = AddNameData(buf, 0)) >= 0)
   895                                  xmlbase = &namedata[index];
   896                  }
   897                  if (GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) == 0)
   898                          return 0; // no voice change
   899                  return CLAUSE_VOICE;
   900          case SSML_VOICE:
   901                  if (GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) == 0)
   902                          return 0; // no voice change
   903                  return CLAUSE_VOICE;
   904          case SSML_SPEAK + SSML_CLOSE:
   905                  // unwind stack until the previous <voice> or <speak> tag
   906                  while ((*n_ssml_stack > 1) && (ssml_stack[*n_ssml_stack-1].tag_type != SSML_SPEAK))
   907                          (*n_ssml_stack)--;
   908                  return CLAUSE_PERIOD + GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   909          case SSML_VOICE + SSML_CLOSE:
   910                  // unwind stack until the previous <voice> or <speak> tag
   911                  while ((*n_ssml_stack > 1) && (ssml_stack[*n_ssml_stack-1].tag_type != SSML_VOICE))
   912                          (*n_ssml_stack)--;
   913
   914                  terminator = 0; // ??  Sentence intonation, but no pause ??
   915                  return terminator + GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   916          case HTML_BREAK:
   917          case HTML_BREAK + SSML_CLOSE:
   918                  return CLAUSE_COLON;
   919          case SSML_SENTENCE:
   920                  if (ssml_sp->tag_type == SSML_SENTENCE) {
   921                          // new sentence implies end-of-sentence
   922                          voice_change_flag = GetVoiceAttributes(px, SSML_SENTENCE+SSML_CLOSE, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   923                  }
   924                  voice_change_flag |= GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   925                  return CLAUSE_PARAGRAPH + voice_change_flag;
   926          case SSML_PARAGRAPH:
   927                  if (ssml_sp->tag_type == SSML_SENTENCE) {
   928                          // new paragraph implies end-of-sentence or end-of-paragraph
